      "fact": "Axis label 'Year'; tick labels 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023."
    },
    {
      "location": "data line, 2012",
      "fact": "Series value approximately 1200 (just below the 1600 gridline)."
    },
